function riverDistance(x,z){const d=z-0.55*x; return Math.abs(d)} function terrainHeight(x,z){let y=0.18*Math.sin(x*0.18)+0.14*Math.cos(z*0.16); y+=Math.max(0,1-Math.hypot(x+8,z+8)/12)*0.9; y+=Math.max(0,1-Math.hypot(x-8,z-8)/12)*0.9; y-=Math.max(0,1-riverDistance(x,z)/2.6)*0.95; return y}
